"""
Validation script for pipeline outputs.
Runs checks on outputs/t01_selected_indicators.csv, outputs/t05_clean_stops.csv,
outputs/t08_pois_clean.csv, outputs/t10_accessibility_scores.csv, and outputs/t13_city_clusters.csv.
Writes outputs/t14_validation_summary.json on successful execution.
"""

import os
import sys
import json
import csv
from pathlib import Path

OUTPUT_DIR = Path("outputs")
OUTPUTS = [
    "t01_selected_indicators.csv",
    "t05_clean_stops.csv",
    "t08_pois_clean.csv",
    "t10_accessibility_scores.csv",
    "t13_city_clusters.csv",
]

REQUIRED_COLUMNS = {
    "t01_selected_indicators.csv": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
    "t05_clean_stops.csv": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
    "t08_pois_clean.csv": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
    "t10_accessibility_scores.csv": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
    "t13_city_clusters.csv": ["city_id", "city_name", "year", "cluster_id"],
}

def check_file_exists(filepath):
    """Check if file exists."""
    return filepath.exists() and filepath.is_file()

def check_file_not_empty(filepath):
    """Check if file is not empty."""
    if not check_file_exists(filepath):
        return False, "File does not exist"
    size = filepath.stat().st_size
    if size == 0:
        return False, "File is empty"
    return True, "File is not empty"

def check_columns_exist(filepath, expected_cols):
    """Check if file has all expected columns."""
    if not check_file_exists(filepath):
        return False, "File does not exist"
    if not check_file_not_empty(filepath):
        return False, "File is empty"

    try:
        with open(filepath, 'r', newline='') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return False, "File is empty or has no headers"

            for exp_col in expected_cols:
                if exp_col not in reader.fieldnames:
                    return False, f"Missing column: {exp_col}"
    except Exception:
        return False, f"Error reading file: {filepath}"

    return True, "Columns exist"

def check_data_values(filepath, expected_values):
    """Check if file has expected values in a column."""
    if not check_file_exists(filepath):
        return False, "File does not exist"
    if not check_file_not_empty(filepath):
        return False, "File is empty"

    try:
        with open(filepath, 'r', newline='') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return False, "File is empty or has no headers"

            for exp_val in expected_values:
                found = False
                for row in reader:
                    if row.get(exp_val) == exp_val:
                        found = True
                        break
                if not found:
                    return False, f"Expected value not found: {exp_val}"
    except Exception:
        return False, f"Error reading file: {filepath}"

    return True, "Values exist"

def check_file_structure(filepath, required_cols):
    """Check if file has the required column structure."""
    if not check_file_exists(filepath):
        return False, "File does not exist"
    if not check_file_not_empty(filepath):
        return False, "File is empty"

    try:
        with open(filepath, 'r', newline='') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return False, "File is empty or has no headers"

            for col in required_cols:
                if col not in reader.fieldnames:
                    return False, f"Missing column: {col}"
    except Exception:
        return False, f"Error reading file: {filepath}"

    return True, "Structure is correct"

def run_checks():
    """Run all validation checks."""
    results = []

    for filename in OUTPUTS:
        filepath = OUTPUT_DIR / filename

        # Check 1: File exists
        exists, msg = check_file_exists(filepath)
        if not exists:
            results.append({
                "check_name": "file_exists",
                "passed": False,
                "message": msg
            })
            continue

        # Check 2: File is not empty
        not_empty, msg = check_file_not_empty(filepath)
        if not not_empty:
            results.append({
                "check_name": "file_not_empty",
                "passed": False,
                "message": msg
            })
            continue

        # Check 3: Required columns exist
        columns_ok, msg = check_columns_exist(filepath, REQUIRED_COLUMNS[filename])
        if not columns_ok:
            results.append({
                "check_name": "columns_exist",
                "passed": False,
                "message": msg
            })
            continue

        # Check 4: File has expected values
        values_ok, msg = check_data_values(filepath, REQUIRED_COLUMNS[filename])
        if not values_ok:
            results.append({
                "check_name": "data_values",
                "passed": False,
                "message": msg
            })
            continue

        # Check 5: File has correct structure
        structure_ok, msg = check_file_structure(filepath, REQUIRED_COLUMNS[filename])
        if not structure_ok:
            results.append({
                "check_name": "file_structure",
                "passed": False,
                "message": msg
            })
            continue

        # All checks passed for this file
        results.append({
            "check_name": "file_complete",
            "passed": True,
            "message": "All checks passed"
        })

    # Write JSON summary
    with open("outputs/t14_validation_summary.json", 'w') as f:
        json.dump(results, f, indent=2)

    return results

if __name__ == "__main__":
    results = run_checks()
    print(json.dumps(results, indent=2))
    sys.exit(0 if all(r["passed"] for r in results) else 1)
