        return False, "missing"
    size = filepath.stat().st_size
    if size == 0:
        return False, "empty"
    return True, "not_empty"


def check_columns_exist(filepath, expected_cols):
    if not check_file_exists(filepath):
        return False, "missing"
    if not check_file_not_empty(filepath):
        return False, "empty"

    try:
        with open(filepath, "r", newline="") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return False, "empty"

            for exp_col in expected_cols:
                if exp_col not in reader.fieldnames:
                    return False, f"missing: {exp_col}"
    except Exception:
        return False, "error"

    return True, "columns"


def check_data_values(filepath, expected_values):
    if not check_file_exists(filepath):
        return False, "missing"
    if not check_file_not_empty(filepath):
        return False, "empty"

    try:
        with open(filepath, "r", newline="") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return False, "empty"

            for exp_val in expected_values:
                found = False
                for row in reader:
                    if row.get(exp_val) == exp_val:
                        found = True
                        break
                if not found:
                    return False, f"missing: {exp_val}"
    except Exception:
        return False, "error"

